<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import AdminDialog from './AdminDialog.vue';import PlatformPermissionCatalog from './PlatformPermissionCatalog.vue';const props=defineProps<{csrf?:string}>();const emit=defineEmits(['changed']);const catalogOpen=ref(false);const rows=ref<any[]>([]),permissions=ref<any[]>([]),editor=ref<any>(null),error=ref(''),message=ref(''),busy=ref(false),search=ref('');
async function request(path='',method='GET',body?:any){const r=await fetch('/pms/api/roles'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Unable to complete this action.');return d;}
async function load(){try{const d=await request();rows.value=d.data;permissions.value=d.permissions;}catch(e){error.value=(e as Error).message;}}
function edit(row?:any){error.value='';search.value='';editor.value=row?{...row,permission_ids:row.permissions.map((p:any)=>p.id)}:{role_name:'',role_key:'',permission_ids:[]};}
async function save(){busy.value=true;error.value='';try{message.value=(await request(editor.value.id?'/'+editor.value.id:'','POST',editor.value)).message;editor.value=null;await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(row:any){if(!confirm('Delete PMS role '+row.role_name+'? Users lose permissions granted by this role.'))return;busy.value=true;error.value='';try{message.value=(await request('/'+row.id,'DELETE')).message;await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><div class="admin-section-heading"><div><h2>Product roles &amp; permissions</h2><p class="muted">PMS roles retain their existing permission keys and department/project workflow. They do not grant Judibas or Communication administration.</p></div><button class="button primary" @click="edit()">Create PMS role</button></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
<AdminDialog v-if="editor" :title="editor.id?'Edit PMS role':'Create PMS role'" subtitle="Select the permissions this role should grant." :busy="busy" @close="editor=null"><form class="admin-editor" @submit.prevent="save"><label>Role name<input v-model="editor.role_name" required maxlength="255"></label><label>Role key<input v-model="editor.role_key" required pattern="[a-zA-Z0-9_-]+" maxlength="255"></label><label>Find permissions<input v-model="search" type="search"></label><div class="editor-actions"><button type="button" class="button" @click="editor.permission_ids=permissions.map(p=>p.id)">Select all</button><button type="button" class="button" @click="editor.permission_ids=[]">Clear</button></div><fieldset class="role-permission-options"><legend>PMS permissions</legend><label class="check" v-for="p in permissions.filter(p=>(p.permission_name+' '+p.permission_key).toLowerCase().includes(search.toLowerCase()))" :key="p.id"><input type="checkbox" v-model="editor.permission_ids" :value="p.id"><span>{{p.permission_name}} <small class="muted">({{p.permission_key}})</small></span></label></fieldset><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div class="editor-actions"><button class="button primary" :disabled="busy">{{busy?'Saving...':'Save role'}}</button><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button></div></form></AdminDialog>
<div class="admin-list admin-role-list"><article v-for="row in rows" :key="row.id"><div><strong>{{row.role_name}}</strong><p class="muted">PMS &middot; {{row.role_key}} &middot; {{row.permissions.length}} permissions</p></div><div class="row-actions"><button @click="edit(row)">Edit</button><button :disabled="busy" @click="remove(row)">Delete</button></div></article></div><button class="button" @click="catalogOpen=!catalogOpen">{{catalogOpen?'Hide':'Manage'}} permission catalogue</button><PlatformPermissionCatalog v-if="catalogOpen" :csrf="csrf" @changed="load();emit('changed')"/></template>
<style scoped>.role-permission-options{max-height:360px;overflow:auto;display:grid;gap:10px;padding:16px;border:1px solid var(--line);border-radius:8px}</style>
